<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { apiRequest, listAgents } from './api'

type Scope = { include_agents: boolean; include_global_config: boolean; include_secrets: boolean; include_skill_pool: boolean }
type Backup = { id: string; name: string; description?: string; created_at: string; agent_count: number; scope: Scope; version?: string }
type BackupDetail = Backup & { workspace_stats: Record<string, { files: number; size: number }> }
type Job = { job_id: string; status: string; percent: number; phase: string; current_agent?: string; agent_index?: number; total_agents?: number; error?: string }

const backups = ref<Backup[]>([]), agentIds = ref<string[]>([]), error = ref(''), notice = ref(''), loading = ref(false), creating = ref(false)
const progress = ref<Job | null>(null), fileInput = ref<HTMLInputElement | null>(null), pendingToken = ref(''), conflict = ref<Backup | null>(null), importing = ref(false)
const createOpen = ref(false), restoreOpen = ref(false), selected = ref<BackupDetail | null>(null), restoreConfirmed = ref(false)
const createForm = ref({ name: '', description: '', mode: 'full', agents: [] as string[], scope: { include_agents: true, include_global_config: true, include_secrets: false, include_skill_pool: true } })
const restoreForm = ref({ mode: 'full', agent_ids: [] as string[], include_agents: true, include_global_config: true, include_secrets: false, include_skill_pool: true, preserve_local_protected_config: true })

function authHeaders(): Record<string, string> { const token = window.localStorage.getItem('majo_auth_token'); return token ? { Authorization: `Bearer ${token}` } : {} }
function clean() { error.value = ''; notice.value = '' }
function fullScope(): Scope { return { include_agents: true, include_global_config: true, include_secrets: true, include_skill_pool: true } }
function createScope(): Scope { return createForm.value.mode === 'full' ? fullScope() : { ...createForm.value.scope, include_agents: createForm.value.agents.length > 0 } }
function restoreScope() { return restoreForm.value.mode === 'full' ? { ...fullScope(), mode: 'full', agent_ids: selected.value ? Object.keys(selected.value.workspace_stats) : [], preserve_local_protected_config: restoreForm.value.preserve_local_protected_config } : { ...restoreForm.value, mode: 'custom' } }
async function refresh() { loading.value = true; try { backups.value = await apiRequest<Backup[]>('/backups'); error.value = '' } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not load backups.' } finally { loading.value = false } }
async function waitForJob(id: string) { for (;;) { const job = await apiRequest<Job>(`/backups/jobs/${encodeURIComponent(id)}`); progress.value = job; if (job.status === 'completed') return; if (job.status === 'failed' || job.status === 'cancelled') throw new Error(job.error || 'Backup did not complete.'); await new Promise(resolve => window.setTimeout(resolve, 350)) } }
async function create() { creating.value = true; clean(); progress.value = null; try { const scope = createScope(); const job = await apiRequest<Job>('/backups/jobs', { method: 'POST', body: JSON.stringify({ name: createForm.value.name.trim() || `Workspace backup ${new Date().toLocaleString()}`, description: createForm.value.description.trim(), scope, agents: scope.include_agents ? createForm.value.agents : [] }) }); await waitForJob(job.job_id); notice.value = 'Backup created.'; createOpen.value = false; await refresh() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not create backup.' } finally { creating.value = false } }
async function cancel() { if (!progress.value?.job_id) return; try { progress.value = await apiRequest<Job>(`/backups/jobs/${encodeURIComponent(progress.value.job_id)}/cancel`, { method: 'POST' }); notice.value = 'Backup cancellation requested.' } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not cancel backup.' } }
async function openRestore(backup: Backup) { clean(); restoreOpen.value = true; restoreConfirmed.value = false; selected.value = null; try { const detail = await apiRequest<BackupDetail>(`/backups/${encodeURIComponent(backup.id)}`); selected.value = detail; restoreForm.value = { mode: detail.scope.include_agents && detail.scope.include_global_config && detail.scope.include_skill_pool ? 'full' : 'custom', agent_ids: Object.keys(detail.workspace_stats), include_agents: detail.scope.include_agents, include_global_config: detail.scope.include_global_config, include_secrets: detail.scope.include_secrets, include_skill_pool: detail.scope.include_skill_pool, preserve_local_protected_config: true } } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not inspect backup.'; restoreOpen.value = false } }
async function restore() { if (!selected.value || !restoreConfirmed.value) return; clean(); try { const result = await apiRequest<{ preserved_local_keys?: string[] }>(`/backups/${encodeURIComponent(selected.value.id)}/restore`, { method: 'POST', body: JSON.stringify(restoreScope()) }); notice.value = result.preserved_local_keys?.length ? `Backup restored. Preserved local settings: ${result.preserved_local_keys.join(', ')}.` : 'Backup restored.'; restoreOpen.value = false } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not restore backup.' } }
async function remove(id: string) { if (!window.confirm('Delete this backup?')) return; try { await apiRequest('/backups/delete', { method: 'POST', body: JSON.stringify({ ids: [id] }) }); await refresh() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not delete backup.' } }
async function importArchive(event: Event, trustMode?: string) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; importing.value = true; clean(); const form = new FormData(); form.append('file', file); try { const response = await fetch(`/api/backups/import${trustMode ? `?trust_mode=${encodeURIComponent(trustMode)}` : ''}`, { method: 'POST', headers: authHeaders(), body: form }); const body = await response.json().catch(() => ({})); if (response.status === 409 && body.detail === 'backup_conflict') { pendingToken.value = body.pending_token; conflict.value = body.existing as Backup; return } if (!response.ok) throw new Error(body.detail || `Import failed (HTTP ${response.status}).`); notice.value = 'Backup imported.'; await refresh() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not import backup.' } finally { importing.value = false; if (fileInput.value) fileInput.value.value = '' } }
async function overwriteImport() { if (!pendingToken.value) return; clean(); try { await apiRequest(`/backups/import?pending_token=${encodeURIComponent(pendingToken.value)}`, { method: 'POST' }); pendingToken.value = ''; conflict.value = null; notice.value = 'Backup overwritten and imported.'; await refresh() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not overwrite backup.' } }
function toggleCreateAgent(id: string) { const selectedAgents = createForm.value.agents; const index = selectedAgents.indexOf(id); if (index >= 0) selectedAgents.splice(index, 1); else selectedAgents.push(id) }
function toggleRestoreAgent(id: string) { const selectedAgents = restoreForm.value.agent_ids; const index = selectedAgents.indexOf(id); if (index >= 0) selectedAgents.splice(index, 1); else selectedAgents.push(id) }
function size(value: number) { if (value < 1024) return `${value} B`; if (value < 1024 * 1024) return `${Math.round(value / 1024)} KB`; return `${(value / (1024 * 1024)).toFixed(1)} MB` }
onMounted(async () => { await refresh(); try { agentIds.value = (await listAgents()).agents.map(agent => agent.id); createForm.value.agents = [...agentIds.value] } catch { /* A backup can still include all profiles server-side. */ } })
</script>
<template>
  <section class="settings-page backups-page"><header class="settings-heading"><div><p class="eyebrow">DATA</p><h1>Backups</h1></div><span class="skills-editor-actions"><input ref="fileInput" type="file" accept=".zip,application/zip" hidden @change="importArchive"><button :disabled="importing" @click="fileInput?.click()">{{ importing ? 'Importing…' : 'Import' }}</button><button @click="createOpen = !createOpen">Create backup</button></span></header>
    <p v-if="error" class="inline-error" role="alert">{{ error }}</p><p v-if="notice" class="success-notice">{{ notice }}</p>
    <section v-if="createOpen" class="settings-card backup-form"><h2>Create backup</h2><form class="stacked-form" @submit.prevent="create"><label>Name <input v-model="createForm.name" placeholder="Optional backup name" /></label><label>Description <input v-model="createForm.description" placeholder="Optional description" /></label><label>Scope <select v-model="createForm.mode"><option value="full">Full backup</option><option value="partial">Custom scope</option></select></label><template v-if="createForm.mode === 'partial'"><label class="skills-checkbox"><input v-model="createForm.scope.include_global_config" type="checkbox" /> Global configuration</label><label class="skills-checkbox"><input v-model="createForm.scope.include_skill_pool" type="checkbox" /> Skill pool</label><label class="skills-checkbox"><input v-model="createForm.scope.include_secrets" type="checkbox" /> Secrets</label><fieldset><legend>Agent workspaces</legend><label v-for="id in agentIds" :key="id" class="skills-checkbox"><input :checked="createForm.agents.includes(id)" type="checkbox" @change="toggleCreateAgent(id)" /> {{ id }}</label></fieldset></template><div class="skills-editor-actions"><button type="submit" class="primary" :disabled="creating">{{ creating ? 'Creating…' : 'Create backup' }}</button><button type="button" @click="createOpen = false">Cancel</button></div></form></section>
    <section v-if="progress" class="settings-card backup-progress"><strong>{{ progress.phase }}</strong><span>{{ progress.percent }}%</span><progress :value="progress.percent" max="100" /><small v-if="progress.current_agent">{{ progress.current_agent }} · {{ progress.agent_index }}/{{ progress.total_agents }}</small><button v-if="progress.status === 'running' || progress.status === 'cancel_requested'" :disabled="progress.status === 'cancel_requested'" @click="cancel">{{ progress.status === 'cancel_requested' ? 'Cancelling…' : 'Cancel backup' }}</button></section>
    <section v-if="restoreOpen && selected" class="settings-card backup-form"><h2>Restore {{ selected.name || selected.id }}</h2><p class="muted">Choose what to restore, then confirm the destructive operation.</p><form class="stacked-form" @submit.prevent="restore"><label>Restore mode <select v-model="restoreForm.mode"><option value="full">Full restore</option><option value="custom">Custom restore</option></select></label><template v-if="restoreForm.mode === 'custom'"><label class="skills-checkbox"><input v-model="restoreForm.include_global_config" type="checkbox" /> Global configuration</label><label class="skills-checkbox"><input v-model="restoreForm.include_skill_pool" type="checkbox" /> Skill pool</label><label class="skills-checkbox"><input v-model="restoreForm.include_secrets" type="checkbox" /> Secrets</label><label class="skills-checkbox"><input v-model="restoreForm.include_agents" type="checkbox" /> Agent workspaces</label><fieldset v-if="restoreForm.include_agents"><legend>Workspaces in backup</legend><label v-for="(stats, id) in selected.workspace_stats" :key="id" class="skills-checkbox"><input :checked="restoreForm.agent_ids.includes(id)" type="checkbox" @change="toggleRestoreAgent(id)" /> {{ id }} · {{ stats.files }} files · {{ size(stats.size) }}</label></fieldset></template><label class="skills-checkbox"><input v-model="restoreForm.preserve_local_protected_config" type="checkbox" /> Preserve local security, provider, and routing configuration</label><label class="skills-checkbox"><input v-model="restoreConfirmed" type="checkbox" /> I understand this can replace local files and settings</label><div class="skills-editor-actions"><button type="submit" class="primary" :disabled="!restoreConfirmed">Restore backup</button><button type="button" @click="restoreOpen = false">Cancel</button></div></form></section>
    <section v-if="conflict" class="settings-card backup-conflict"><h2>Backup already exists</h2><p>A backup with ID <strong>{{ conflict.id }}</strong> already exists. Overwrite it with the imported archive?</p><div class="skills-editor-actions"><button class="primary" @click="overwriteImport">Overwrite and import</button><button @click="conflict = null; pendingToken = ''">Keep existing backup</button></div></section>
    <div class="settings-card"><p v-if="loading">Loading backups…</p><p v-else-if="!backups.length" class="muted">No backups yet.</p><article v-for="backup in backups" :key="backup.id" class="skills-item backup-row"><span><strong>{{ backup.name || backup.id }}</strong><small>{{ backup.created_at }} · {{ backup.agent_count }} agents · {{ backup.scope.include_secrets ? 'Includes secrets' : 'Secrets excluded' }}</small></span><span class="skills-editor-actions"><a :href="`/api/backups/${encodeURIComponent(backup.id)}/export`">Export</a><button @click="openRestore(backup)">Restore</button><button @click="remove(backup.id)">Delete</button></span></article></div>
  </section>
</template>
